var _markdown = "\n\n`CRadar.h`\n\nBlip 句柄跨帧要自己存；清标用 `ClearBlip`。\n\n## 坐标 Blip [#坐标-blip]\n\n<Api name=\"SetCoordBlip / SetShortRangeCoordBlip\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static int SetCoordBlip(eBlipType type, CVector posn, unsigned int arg2, eBlipDisplay blipDisplay, char* scriptName);\n      static int SetShortRangeCoordBlip(eBlipType type, CVector posn, unsigned int arg2, eBlipDisplay blipDisplay, char* scriptName);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      int blip = CRadar::SetCoordBlip(BLIP_COORD, pos, 0, BLIP_DISPLAY_BOTH, nullptr);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 实体 Blip [#实体-blip]\n\n<Api name=\"SetEntityBlip / ClearBlipForEntity\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static int SetEntityBlip(eBlipType type, int entityHandle, unsigned int arg2, eBlipDisplay blipDisplay);\n      static void ClearBlipForEntity(eBlipType blipType, int entityHandle);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // int handle = CPools::GetPedRef(ped);\n      // int blip = CRadar::SetEntityBlip(BLIP_CHAR, handle, 0, BLIP_DISPLAY_BOTH);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 改 Blip 外观 [#改-blip-外观]\n\n<Api name=\"ChangeBlipColour / SetBlipSprite / ChangeBlipScale\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void ChangeBlipColour(int blipIndex, unsigned int color);\n      static void ChangeBlipScale(int blipIndex, int size);\n      static void ChangeBlipDisplay(int blipIndex, eBlipDisplay blipDisplay);\n      static void SetBlipSprite(int blipIndex, int spriteId);\n      static void SetBlipFriendly(int blipIndex, unsigned char friendly);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CRadar::ChangeBlipColour(blip, BLIP_COLOUR_YELLOW);\n      CRadar::SetBlipSprite(blip, RADAR_SPRITE_WAYPOINT); // 以枚举为准\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 清除 Blip [#清除-blip]\n\n<Api name=\"ClearBlip / ClearActualBlip\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void ClearBlip(int blipIndex);\n      static void ClearActualBlip(int blipArrId);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CRadar::ClearBlip(blip);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 雷达画区域 [#雷达画区域]\n\n<Api name=\"DrawAreaOnRadar\">\n  绘制帧 / 雷达钩子里用。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void DrawAreaOnRadar(CRect const& rect, CRGBA const& color, bool inMenu);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // CRadar::DrawAreaOnRadar(rect, color, false);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 常用枚举 [#常用枚举]\n\n<Api name=\"eBlipType / eBlipDisplay / eBlipColour\">\n  见 `CRadar.h`。\n\n  ```cpp\n  // BLIP_COORD, BLIP_CHAR, BLIP_CAR, BLIP_OBJECT, BLIP_PICKUP ...\n  // BLIP_DISPLAY_BOTH, BLIP_DISPLAY_BLIP_ONLY ...\n  ```\n</Api>\n";
